    "narration": "עכשיו אנו מגיעים לתיאטרון סלובצקי המרשים, אחד מהסמלים התרבותיים הבולטים של קרקוב ומקדש אמיתי לדרמה הפולנית. התיאטרון נפתח בשנת 1893 ונקרא על שם יוליוש סלובצקי, מהמשוררים הרומנטיים הגדולים של פולין, והפך במהרה לפנינה תרבותית של העיר.\n\nהארכיטקטורה של התיאטרון היא חגיגה לעיניים, בהשראת בתי האופרה הגדולים של פריז ווינה. המבנה עוצב על ידי יאן זאבייסקי ומציג חזית נאו-בארוקית עשירה, עם פסלים, עמודים וכיפה מרשימה שבראשה פסלי אלגוריה. בכניסה יחכו לכם גרם מדרגות שיש, קישוטי זהב ונברשות נוצצות. האולם המרכזי מרשים לא פחות, עם מושבים אדומים קטיפתיים, יציעים מעוטרים ותקרה מצוירת בידי האמן אנטוני טאוך.\n\nלאורך השנים אירח התיאטרון כמה מן הבכורות החשובות בתולדות התיאטרון הפולני, ובהן ההצגה הראשונה של \"החתונה\" מאת סטניסלב ויספיאנסקי בשנת 1901. רבים מהשחקנים הגדולים של פולין הופיעו על בימתו, והתיאטרון הופיע בספרים, ציורים וסרטים רבים, כסמל למסורת האמנותית של קרקוב.\n\nהמבנה עצמו חווה לא מעט דרמות – גם על הבמה וגם מחוצה לה. בתקופת הכיבוש הנאצי במלחמת העולם השנייה, התיאטרון נסגר ושימש כמרכז תרבות גרמני. לאחר המלחמה הפך לסמל של התחדשות, עם הופעות שחגגו את הזהות הפולנית והחוסן הלאומי.\n\nישנן גם אגדות משעשעות סביב התיאטרון. סיפור אחד מספר שרוחה של שחקנית לשעבר עדיין משוטטת במסדרונות מאחורי הקלעים, ומדי פעם מעניקה חיוך מעודד לשחקנים צעירים. מסורת אחרת גורסת שליטוף פסל הברונזה של סלובצקי בלובי לפני הופעה מביא מזל טוב לשחקנים ולקהל כאחד.\n\nכיום, תיאטרון סלובצקי נמצא בלב חיי התרבות של קרקוב. הוא מארח הצגות, אופרות וקונצרטים, ומושך אליו חובבי תיאטרון מכל רחבי פולין והעולם. אם יש לכם הזדמנות, כנסו להצגה או פשוט התפעלו מהיופי של המבנה. ואנקדוטה משעשעת: בפסטיבל התיאטרון השנתי, שחקנים יוצאים לכיכר שלפני התיאטרון ומבצעים קטעים לקהל הרחוב – תזכורת לכך שבקרקוב, האמנות והחיים תמיד שזורים זה בזה.",
    "teaser": "התחנה הבאה שלנו: תיאטרון סלובצקי. תיאטרון מפואר מהמאה ה-19, אחד מאבני החן האדריכליות של קרקוב.",
