    "narration": "ברוכים הבאים לאחוזת \"פוד אורלם\", אחד הבתים ההיסטוריים והייחודיים ביותר בכיכר השוק המרכזית של קרקוב. המבנה נבנה במחצית השנייה של המאה ה-14, והוא עד למאות שנים של היסטוריה עירונית, תוך שהוא משנה בעלים ותפקידים יחד עם השתנות העיר. השיפוץ המשמעותי הראשון התרחש במפנה המאות ה-14 וה-15, ובמאה ה-16 קיבלה האחוזה את צורתה הרנסנסית, כולל אגף נוסף.\n\nלאורך השנים פעלו כאן עסקים מגוונים. ב-1569 פתח וויצ'ך סוליקובסקי בית מרקחת בקומת הקרקע, ששרד מאות שנים והפך לחלק בלתי נפרד מזהות המבנה. במאה ה-18 פעל כאן בית קפה וחדר סנוקר, וב-1809 חזר המקום לשמש כבית מרקחת \"פוד ביאווים אורלם\" (מתחת לעיט הלבן). בסוף המאה ה-19 שופצה האחוזה בידי בעליה אדולף סידלצקי, בתכנון ולדיסלב אקיילסקי, נוספו לה קומות והחזית קיבלה את המראה הגותי-רנסנסי המוכר כיום.\n\nגולת הכותרת של המבנה היא פסל עוף החול שבראשו – דמות מרשימה שמבלבלת רבים וחושבים שמדובר בעיט. הפסל עוצב בידי סטניסלב ויספיאנסקי ויוצר בידי יוליאן שופינסקי, והוא מעניק למבנה נופך אמנותי ומסתורי. בעבר עיטרו את הפנים רהיטים עם עיטורי עופות, אך אלו הוסרו בסוף שנות ה-90.\n\nקירות האחוזה ראו דורות של תושבי קרקוב – מהכרוניקן ברתולומיי קרומר במאה ה-16 ועד לתרבות בתי הקפה של המאות ה-18 וה-19. מיקומה בלב הכיכר הפך אותה לעדה לתהלוכות מלכותיות, חגיגות ציבוריות וחיי היומיום של העיר.\n\nכיום, \"פוד אורלם\" הוא עד חי להיסטוריה וליופי הארכיטקטוני של קרקוב. בית המרקחת כבר לא פועל, אך המבנה נותר חלק אהוב מנוף הכיכר. ואנקדוטה משעשעת: מבקרים רבים נוגעים בפסל עוף החול למזל טוב, בתקווה לזכות בכוח ההתחדשות האגדי שלו.",
    "teaser": "התחנה הבאה שלנו: אחוזת \"פוד אורלם\". בית עירוני היסטורי בכיכר המרכזית, ידוע בחזית גותית-רנסנסית ופסל עוף החול, עם מורשת של בית מרקחת, תרבות ואגדה.",
