    "narration": "כאן אנו מגיעים לאחת הדמויות הצבעוניות והאהובות של קרקוב – אנדרטת פיוטר סקרז'נצקי, אגדה של חיי הלילה והתרבות של העיר. תמצאו אותו יושב ליד שולחן ברונזה קטן ממש מחוץ לבר Vis-à-vis, בלב כיכר השוק. סקרז'נצקי היה המייסד והנשמה של קברט \"פיבניצה פוד ברנמי\", מועדון המרתף שהפך לסמל של רוח יצירתית, הומור עדין ומרד תרבותי בקרקוב.\n\nסקרז'נצקי הגיע לקרקוב אחרי מלחמת העולם השנייה, למד היסטוריה של האמנות באוניברסיטת יגיילוניה, וב-1956 הקים את הקברט שהפך למוסד איקוני בפולין. במשך יותר מארבעים שנה הוביל את \"פיבניצה\" עם שנינות חדה, סגנון אקסצנטרי ויכולת לצחוק גם בזמנים הקשים של המשטר הקומוניסטי. הוא היה ידוע במסיבותיו הפרועות, ימי ההולדת האגדיים והגישה המרדנית שהפכה אותו לגיבור לאמנים ולחובבי חופש.\n\nהאנדרטה, מעשה ידיה של גז'ינה בורקובסקה-נימויאבסקה ולוקאש נימויאבסקי, הוצבה בשנת 2000. היא מציגה את סקרז'נצקי יושב במקומו הקבוע, עם כוס קפה ומאפרה, כאילו הוא מחכה לחברים שיצטרפו לשיחה. הפסל ממוקם ליד הקברט המפורסם, והבר עצמו שימש לו \"משרד\" לא רשמי – עד כדי כך שהיה מקום מפגש קבוע לאנשי רוח ואמנים.\n\nבמהלך השנים הפכה האנדרטה לנקודת ציון אהובה ולמקום מפגש לאמנים, סטודנטים ובליינים. יש מסורת לשבת ליד השולחן של סקרז'נצקי לצילום, ויש אף שמניחים פרחים, שירים או כוסית וודקה לכבודו. למעשה, העיר נאלצה להזכיר לאחרונה שאסור לשתות ליד הפסל – אף שזה מפתה במיוחד!\n\nרוחו של סקרז'נצקי ממשיכה לחיות בסצנה התרבותית של קרקוב, והאנדרטה מזכירה לכולנו לא לקחת את עצמנו – או את האמנות – ברצינות יתרה. אם יתמזל מזלכם, אולי תיתקלו כאן במופע רחוב או זמר קברט שמוקיר את זכרו. ואנקדוטה חביבה: המקומיים אומרים שאם תלחשו בדיחה או חרוז לפסל, תזכו בלילה מוצלח ובמזל טוב בקרקוב!",
