    "narration": "ממש מתחת לפני השטח הסואן של כיכר השוק המרכזית מסתתר מוזיאון רינק התת-קרקעי – מסע ייחודי אל עברה של קרקוב. המוזיאון נפתח ב-2010 ונבנה סביב שרידים ארכיאולוגיים אותנטיים שהתגלו בחפירות ראשית המאה ה-21. כאן אתם הולכים ממש בתוך שכבות ההיסטוריה של העיר – מההתיישבות הקדומה ועד השוק התוסס של ימי הביניים.\n\nעיצוב המוזיאון משלב חדשנות מודרנית עם שימור קפדני. תטיילו על גשרים מזכוכית מעל יסודות דוכני שוק, סדנאות ובית מלאכה משוחזר מהמאה ה-12. בין המוצגים המרשימים: גוש עופרת ענק במשקל 693 ק\"ג, מטבעות, תכשיטים, כלי עבודה וחפצים יומיומיים שממחישים את חיי היום-יום של תושבי קרקוב בימי הביניים.\n\nהמוזיאון מחייה את ההיסטוריה בעזרת תצוגות מולטימדיה מתקדמות, הולוגרמות ומסכים אינטראקטיביים. תוכלו לראות כיצד השתנתה הכיכר לאורך הדורות, לעקוב אחרי נתיבי מסחר עתיקים, ואף לחוות את קולות וריחות השוק כפי שהיה לפני 700 שנה. תמצאו כאן גם קברים מתקופות קדומות ושרידי יישוב שנחרב בפלישה טטרית.\n\nהמקום עורר השראה בקרב סופרים, היסטוריונים ובמאים, ונחשב לאחת האטרקציות הפופולריות בעיר. המוזיאון מארח מבקרים מכל העולם, כולל תלמידים, חוקרים וסיורי לילה מיוחדים – כי לפי האגדה, רוחות סוחרי ימי הביניים עדיין משגיחות על הדוכנים הישנים.\n\nכיום, מוזיאון רינק התת-קרקעי הוא מהמבוקרים בעיר. יש בו מסלולים קצרים וארוכים, בית קפה קטן וחנות מזכרות. ואנקדוטה חביבה: הכניסה כל כך דיסקרטית, שרבים חולפים על פניה מבלי לשים לב – חפשו את הפירמידה מזכוכית והכניסה ליד אולם הבדים. מי שייכנס, יגלה עולם נסתר שרוב המבקרים בקרקוב כלל לא יודעים על קיומו!",
    "teaser": "התחנה הבאה שלנו: מוזיאון רינק התת-קרקעי. מוזיאון אינטראקטיבי מתחת לכיכר המרכזית, החושף את עברה של קרקוב בימי הביניים.",
