    "narration": "ברוכים הבאים לקולגיום מאיוס, הבניין העתיק ביותר של האוניברסיטה העתיקה ביותר בפולין ואבן חן אמיתית של המורשת האקדמית והאדריכלית של קרקוב. הבניין המרשים הזה ניצב בפינת הרחובות שוו. אנה ויגיילונסקה, ומשמש את ליבת אוניברסיטת יגיילוניה מאז ראשית המאה ה-15. האוניברסיטה עצמה נוסדה ב-1364 בידי המלך קז'ימייז' הגדול, אך היה זה המלך ולדיסלב יגיילו, בכספי המלכה ידוויגה, שרכש את הנכס הזה לאוניברסיטה בשנת 1400 – וכך החלה ההיסטוריה הארוכה כאן.\n\nקולגיום מאיוס הוא יצירת מופת גותית, ששופצה בסוף המאה ה-15 לכדי חצר מרובעת הרמונית עם גלריות מקומרות המקיפות חצר שליווה. החזיתות האדומות, הקשתות המחודדות והגמלונים הדקורטיביים משקפים את סגנון תור הזהב של קרקוב. במרכז החצר תמצאו באר משנת 1517, והקלוייסטרים נתמכים בעמודי אבן אלגנטיים. בקומות העליונות התגוררו בעבר פרופסורים, ובחדרי הקרקע התקיימו הרצאות וויכוחים מלומדים.\n\nבפנים תגלו אוצרות היסטוריים: חדר הפרופסורים (Stuba Communis), אולם האסיפות עם אוסף ציורים, הספרייה וחדר קופרניקוס – בו מוצגים מכשירים אסטרונומיים מימי הביניים ואסטרולב משנת 1054. ניקולאוס קופרניקוס, האסטרונום הדגול, למד כאן בשנות ה-90 של המאה ה-15. המוזיאון מציג גם שרביטי רקטור גותיים, גלובוס יגיילוניה, מטבעות, מדליות ומכשירים מדעיים נדירים.\n\nקולגיום מאיוס שזור באגדות קרקוב ובספרות ואמנות עולמית. הבניין מופיע בסרטים ובספרים רבים על מסורת הלימוד של קרקוב.\n\nבמהלך הדורות עברה האוניברסיטה תקופות של שפל ופריחה – מהפטרונות של המלכה ידוויגה במאה ה-15, דרך שגשוג במאות ה-19 וה-20, ועד בוגרים דגולים כויסלבה שימבורסקה, איו אנדריץ' ואפילו האפיפיור יוחנן פאולוס השני.\n\nכיום, קולגיום מאיוס הוא מוזיאון אוניברסיטאי המקבל מבקרים מכל העולם. תוכלו לשוטט בין החדרים ההיסטוריים, להתרשם ממכשירים מדעיים עתיקים ולספוג את אווירת מאות שנות לימוד. ואנקדוטה חביבה: בכל שעה עגולה, מתעורר לחיים השעון המכני בחצר, ודמויות עץ של פרופסורים וסטודנטים צועדות בתהלוכה – תזכורת לכך שבקולגיום מאיוס, המסורת והידע הולכים יד ביד.",
    "teaser": "התחנה הבאה שלנו: קולגיום מאיוס. הבניין העתיק ביותר של אוניברסיטת יגיילוניה, נוסד במאה ה-14.",
