    "title": "אבן החכמים",
    "summary": "חפץ מיתולוגי בחצר קולגיום מאיוס, הקשור לאגדות אלכימיה.",
    "description": "ברוכים הבאים לחצר הקסומה של קולגיום מאיוס, שם שזורים אגדות והיסטוריה סביב מה שמכונה \"אבן החכמים\". כאן, בלב הבניין העתיק ביותר של אוניברסיטת יגיילוניה, סופרו במשך מאות שנים סיפורים על אלכימאים, חוקרים והחיפוש הנצחי אחר סודות הטבע.\n\nאבן החכמים, כפי שתוארה באגדות ימי הביניים והרנסנס, נחשבה לבעלת כוח להפוך מתכות פשוטות לזהב ולהעניק חיי נצח. לפי האגדות הקרקובאיות, ממש כאן בקולגיום מאיוס חיפשו האלכימאים המפורסמים של העיר – בהם טורדובסקי האגדי, \"פאוסט הפולני\" – אחר האבן הנעלמת. יש אף הטוענים כי ד\"ר פאוסטוס עצמו עסק כאן בניסויים סודיים בתקווה לגלות את סוד האבן.\n\nהחצר עצמה היא יצירת מופת גותית מאוחרת, מוקפת גלריות קשתיות ומלאה בהדיהם של מאות שנות דיונים מדעיים. פרופסורים וסטודנטים נהגו להתכנס כאן לשיחות על מדע, פילוסופיה וסודות היקום, וקל לדמיין אלכימאי מתגנב לפינה נסתרת לניסוייו.\n\nעם השנים, אגדת אבן החכמים בקולגיום מאיוס היוותה השראה לסופרים, אמנים ואינספור מבקרים. אומרים שאם תעמדו בחצר ותתנו לדמיון להשתולל, אולי תשמעו לחש של סודות שהעסיקו דורות של חוקרים.\n\nהתחנה הבאה שלנו: קולגיום נובום. הבניין הראשי של אוניברסיטת יגיילוניה, שנבנה במאה ה-19.",
