    "narration": "ברוכים הבאים לקולגיום נובום, מרכז הניאו-גותי המרשים של אוניברסיטת יגיילוניה ואחד מסמליה האקדמיים הבולטים של קרקוב. הבניין הושלם בשנת 1887 לציון 500 שנה לאוניברסיטה, ותוכנן על ידי פליקס קשייז'ארסקי כסמל לעידן חדש בחינוך הפולני, בתקופה שבה קרקוב הייתה תחת שלטון אוסטרי. במקומו עמד בעבר פנימיית הסטודנטים \"ירוזלם\", שנשרפה, והבניין החדש החליף אותה.\n\nחזית הלבנים האדומות, הקשתות המחודדות, הסמלים הדקורטיביים של מייסדי האוניברסיטה והחלונות הגבוהים מעניקים לבניין מראה מרשים. המבנה כמעט מרובע ומקיף שתי חצרות פנימיות, והפורטיקו המרשים פונה אל פארק פלאנטי. בפנים תמצאו גרם מדרגות רחב, תקרות קמרון ואולמות הרצאה מפוארים, כולל אולם האסיפות עם תקרת קסטות כחולה ודיוקנאות רקטורים ודקנים במסגרת מוזהבת.\n\nקולגיום נובום משמש כמרכז הניהולי של האוניברסיטה, עם משרדי הרקטור, סגני הרקטור והנהלה מרכזית. זהו גם מקום לטקסים אקדמיים, כנסים בינלאומיים, קונצרטים ואירועים תרבותיים. מול הכניסה הראשית תמצאו את \"אלון החירות\", שניטע ב-1919 לציון עצמאות פולין.\n\nהבניין שזור בהיסטוריה המודרנית של פולין. ב-6 בנובמבר 1939, הזמינו השלטונות הנאצים כמעט 180 פרופסורים וצוות לכאן, ורימו אותם כדי לעצור ולשלוח אותם למחנות ריכוז במה שנודע כ-\"סונדראקציה קרקוב\". לוח זיכרון באולם ההרצאות מנציחה את האירוע הטרגי ואת תרומתם של הפרופסורים לרוח החופש והמדע.\n\nקולגיום נובום מופיע בספרות, זיכרונות ואמנות כסמל לחיים האינטלקטואליים של קרקוב ולעמידות העיר. באולמותיו התקיימו טקסים עם חתני פרס נובל, ראשי מדינות ודורות של סטודנטים, בהם גם קרול וויטילה, לימים האפיפיור יוחנן פאולוס השני.\n\nכיום, קולגיום נובום הוא המרכז המנהלי והטקסי השוקק של אוניברסיטת יגיילוניה. זהו מקום בו מסורת פוגשת חיים אקדמיים מודרניים, וההיסטוריה נוכחת בכל מסדרון. ואנקדוטה חביבה: אומרים שהבניין מלא כל כך ברוח אקדמית, שסטודנטים נוגעים בדלת הברונזה בכניסה הראשית כדי לזכות במזל טוב במבחנים – מסורת שנמשכת עד היום.",
    "teaser": "התחנה הבאה שלנו: קולגיום נובום. הבניין הראשי של אוניברסיטת יגיילוניה, שנבנה במאה ה-19.",
