    "title": "המוזיאון הארכיאולוגי של קרקוב",
    "summary": "המוזיאון הארכיאולוגי הוותיק בפולין, בית לאוצרות פרהיסטוריים, ימי ביניים ומצריים עתיקים.",
    "description": "ברוכים הבאים למוזיאון הארכיאולוגי של קרקוב, המוסד הוותיק מסוגו בפולין וחלון מסקרן לעבר הרחוק של האזור. המוזיאון נוסד ב-1850 בידי החברה המדעית של קרקוב, בתקופת השלטון האוסטרי, ושימש מרכז לחיים תרבותיים ומדעיים כאשר אגודות פטריוטיות נאסרו. בין מייסדיו היו אינטלקטואלים בולטים כמו מנהל ספריית יגיילוניה והמשורר-חוקר וינצנטי פול.\n\nהתערוכות הראשונות נפתחו ב-1857 בארמון לובומירסקי, וכיום שוכן האוסף בבניין היסטורי ששימש בעבר מבצר, מנזר קרמליתי ואף כלא אוסטרי. אוספי המוזיאון מונים מעל 500,000 פריטים, רובם מתרומות של משפחות אצולה ואספנים פרטיים.\n\nבין התערוכות הקבועות: \"אלי מצרים העתיקה\", \"קדרות פרהיסטורית\", \"גן הקרמיקה\", \"הפרהיסטוריה וימי הביניים של פולין הקטנה\" ו\"עגלות ברונוצ'יצה\". מגולות הכותרת – פסל האל מזברוץ', פסל אבן בן ארבע פנים בגובה כשניים וחצי מטרים, שנמצא ב-1848 והפך לסמל המוזיאון. בתערוכת ברונוצ'יצה מוצג העתק חרס של הכד בן 5,500 השנים, שעליו ציורי עגלות הנחשבים בין התיאורים הקדומים בעולם של כלי רכב בעלי ארבעה גלגלים; המקור שמור באקדמיה הפולנית למדעים ואינו מוצג לציבור.\n\nאוסף מצרים העתיקה כולל סרקופגים, מומיות וממצאים מתקופת הממלכה הקדומה ועד התקופה הקופטית, ורבים מהם הובאו לקרקוב בידי אגיפטולוגים וחיילים פולנים במאות ה-19 וה-20.\n\nהמוזיאון היווה השראה לדורות של חוקרים, אמנים וסופרים, ותערוכותיו הופיעו במדריכים ובסרטים תיעודיים. הגן היפהפה שמאחוריו הוא פנינה נסתרת, מושלמת למנוחה אחרי הסיור.\n\nכיום, המוזיאון ממשיך להיות מרכז תוסס למחקר, חינוך ותרבות, ומארח תערוכות מתחלפות, סדנאות והרצאות. בין אם אתם חובבי היסטוריה עתיקה, סקרנים לגבי שורשי קרקוב או מחפשים גן שקט בלב העיר – זהו אתר חובה במסעכם בקרקוב.\n\nהתחנה הבאה שלנו: כנסיית פטרוס ופאולוס הקדושים. הכנסייה הבארוקית הראשונה במלואה בקרקוב, ידועה בפסלי השליחים ובאקוסטיקה המרשימה שלה.",
    "audio": "audio/archaeological_museum_f263234ae328579f7a03ff69a1f94f47.mp3",
