    "narration": "ברוכים הבאים למוזיאון הארכיבישוף – אוצר ייחודי של אמנות קודש ומקום בעל משמעות היסטורית עמוקה לקרקוב ולעולם הקתולי כולו. המוזיאון שוכן בבתי העיר האלגנטיים ברחוב קאנוניצ'ה 19–21, ומפורסם במיוחד בזכות היותו משכנו של קרול וויטילה – לימים האפיפיור יוחנן פאולוס השני: בבית מספר 19 התגורר בשנים 1953–1958, ולאחר מכן עבר לבית הדיקן הסמוך במספר 21, שם נשאר עד סוף 1967.\n\nהמוזיאון נוסד לראשונה ב-1906 על ידי הקרדינל יאן פוזינה, אך קיבל את צורתו הנוכחית ב-1994, עם דגש מחודש על המורשת הרוחנית של הארכיבישופות ועל מורשתו האישית של יוחנן פאולוס השני. תוך כדי שיטוט בחדרים תגלו אוסף מרתק של למעלה מ-600 יצירות אמנות קודש, מהמאה ה-13 ועד המאה ה-20. בין גולות הכותרת: ציורים ופסלים מימי הביניים והרנסנס, בגדי קודש, עבודות זהב ומלאכת יד דתית מהאזור. בין הפריטים היקרים ביותר נמצא הלוח הצבוע העתיק ביותר בפולין – תיאור קדושים מהכנסייה בעיירה דמבנו פודהלאנסקי מהמאה ה-13.\n\nהמבנה עצמו הוא דוגמה קלאסית לאדריכלות בתים היסטוריים של קרקוב – חזיתות הרמוניות, פנים בארוקי וחצר שלווה. החדרים בהם התגורר יוחנן פאולוס השני נשמרו עם חפציו האישיים, ומעניקים הצצה אינטימית לחייו, לשירותו ולערכים שעיצבו את כהונתו כאפיפיור. תמצאו כאן ספרים, בגדי קודש, מתנות שקיבל ואף את מגלשי הסקי הראשונים שלו משנות ה-50.\n\nמוזיאון הארכיבישוף הוא הרבה יותר מאוסף חפצים – זהו עדות חיה לאמונה, לאמנות ולהיסטוריה שעיצבו את קרקוב לאורך הדורות. המוזיאון מארח תערוכות מתחלפות של אמנות נוצרית עכשווית, וממשיך את מסורת היצירה והרוחניות. מסורת מקומית גורסת כי רגע שקט כאן מביא השראה ושלווה, במיוחד למתעניינים בחייו של יוחנן פאולוס השני או בתרבות הדתית של פולין.\n\nכיום, המוזיאון הוא תחנה חובה לכל מי שרוצה להבין את שורשיה הרוחניים והתרבותיים של קרקוב. בין אם באתם בזכות האמנות, ההיסטוריה או מורשתו של אחד האפיפיורים האהובים בעולם – תמצאו כאן מקום של גילוי, התבוננות ושקט פנימי.",
    "teaser": "התחנה הבאה שלנו: מוזיאון הארכיבישוף. מוזיאון לאמנות קודש ומשכנו לשעבר של הקרדינל קרול וויטילה (האפיפיור יוחנן פאולוס השני).",
