    "narration": "ברוכים הבאים לטירת ואוול והקתדרלה המלכותית – היהלום שבכתר של קרקוב והמקום בו ההיסטוריה הפולנית קמה לתחייה. המתחם המבוצר הזה, המתנשא מעל נהר הוויסלה, שימש במשך מאות שנים כמושב מלכי ומלכות פולין, וללא הגזמה – כל אבן כאן מספרת סיפור.\n\nההיסטוריה של הטירה מתחילה לפני למעלה מאלף שנה. הביצורים הראשונים על גבעת ואוול הופיעו כבר במאה ה-10, ובמאה ה-14 הפך המלך קז'ימייז' הגדול את המקום לארמון גותי מפואר. לאורך השנים, כל מלך הוסיף ושיפץ – כך שניתן למצוא כאן שילוב מרהיב של אדריכלות רומנסקית, גותית, רנסנסית ובארוקית. האדריכלים האיטלקים ברטולומאו ברצ'י ופרנצ'סקו פיורנטינו העניקו לטירה את המראה הרנסנסי במאה ה-16, בעוד מגדלי הקתדרלה והקפלות משקפים מאות של סגנונות.\n\nטירת ואוול הייתה תמיד בלב החיים התרבותיים והפוליטיים של פולין – כאן נערכו הכתרות וקבורות מלכים, והאולמות הדהדו בדיוני הפרלמנט הפולני. הקתדרלה, עם הספינה הגבוהה והקפלות המוזהבות, היא מקום מנוחתם של מלכים, גיבורים לאומיים ומשוררים. בפנים תמצאו אוצרות כמו פעמון זיגמונט – הפעמון ההיסטורי הגדול בפולין – וקברי מלכים כמו זיגמונט השלישי ואסה ויאן סובייסקי.\n\nהטירה והקתדרלה היוו השראה לאינספור יצירות אמנות וספרות – מציוריו של יאן מטייקו, דרך רומנים של סנקביץ', ועד סרטים מודרניים. מתחת לגבעה תמצאו את \"מאורת הדרקון\" – מערה שלפי האגדה שימשה את הדרקון האימתני שהובס בידי מייסד העיר קרקוס. בפסל הדרקון למרגלות הגבעה תוכלו לראות אש אמיתית יוצאת מפיו!\n\nבמהלך הדורות אירחה הטירה אפיפיורים, נשיאים ואורחים רמי מעלה מכל העולם. היא שרדה שריפות, מלחמות וכיבושים – כולל תקופה בה שימשה כקסרקטין צבאי אוסטרי. במאה ה-20 שוקמה הטירה והפכה למוזיאון המציג אוצרות מלכותיים, שטיחי קיר ואחת מאוספי האוהלים העות'מאניים המרשימים באירופה.\n\nכיום, טירת ואוול והקתדרלה הן האתרים המבוקרים ביותר בקרקוב, ומושכות מיליוני מבקרים מדי שנה. החצרות, הגנים והגלריות פתוחים לקהל, והקתדרלה פעילה ומשמשת לטקסים לאומיים.",
    "teaser": "התחנה הבאה שלנו: טירת ואוול והקתדרלה המלכותית. האתר ההיסטורי האיקוני ביותר של קרקוב, מושב מלכי פולין ולב הרוחני של האומה.",
